def fib(n: int) -> int:
    """Return n-th Fibonacci number."""
    if n <= 0:
        raise ValueError("Input must be a positive integer.")

    elif n == 1:
        return 1
    elif n == 2:
        return 1
    else:
        a, b = 0, 1
        for _ in range(3, n + 1):
            a, b = b, a + b
        return b

# Test cases
print(fib(1))  # Output: 55
print(fib(2))  # Output: 1
print(fib(8))  # Output: 21
